// ManualRoute.js
import { useEffect, useRef } from 'react';
import { useMap } from 'react-leaflet';
import L from 'leaflet';
import './App.css';

function ManualRoute({ from, to }) {
  const map = useMap();
  const polylineRef = useRef(null);
  const tooltipRef = useRef(null);

  useEffect(() => {
    if (!from || !to) return;

    const apiKey = 'eyJvcmciOiI1YjNjZTM1OTc4NTExMTAwMDFjZjYyNDgiLCJpZCI6ImY5ODMzM2YwNjA1ZTRmYTlhODE3NDBmMDg5YTVjODc2IiwiaCI6Im11cm11cjY0In0=';
    const url = 'https://api.openrouteservice.org/v2/directions/driving-car/geojson';

    const body = {
      coordinates: [
        [from.lng, from.lat],
        [to.lng, to.lat]
      ]
    };

    const controller = new AbortController();
    const { signal } = controller;

    // Remove previous route before drawing a new one
    if (polylineRef.current) {
      map.removeLayer(polylineRef.current);
      polylineRef.current = null;
    }
    if (tooltipRef.current) {
      map.removeLayer(tooltipRef.current);
      tooltipRef.current = null;
    }

    fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': apiKey
      },
      body: JSON.stringify(body),
      signal
    })
      .then(res => res.json())
      .then(data => {
        if (!data.features || !data.features[0]) throw new Error('No route found');

        const coords = data.features[0].geometry.coordinates;
        const latLngs = coords.map(([lng, lat]) => [lat, lng]);

        const polyline = L.polyline(latLngs, { color: 'blue', weight: 4 }).addTo(map);
        polylineRef.current = polyline;

        const distanceInKm = (data.features[0].properties.summary.distance / 1000).toFixed(2);
        const midpoint = latLngs[Math.floor(latLngs.length / 2)];

        const distanceTooltip = L.tooltip({
          permanent: true,
          direction: 'center',
          className: 'distance-tooltip'
        })
        .setContent(`📏 ${distanceInKm} km`)
        .setLatLng(midpoint)
        .addTo(map);
        tooltipRef.current = distanceTooltip;
      })
      .catch(err => {
        if (err.name === 'AbortError') {
          return;
        }
        console.error('Error fetching route:', err);
        if (polylineRef.current) {
          map.removeLayer(polylineRef.current);
          polylineRef.current = null;
        }
        if (tooltipRef.current) {
          map.removeLayer(tooltipRef.current);
          tooltipRef.current = null;
        }
      });

    return () => {
      controller.abort();
      if (polylineRef.current) {
        map.removeLayer(polylineRef.current);
        polylineRef.current = null;
      }
      if (tooltipRef.current) {
        map.removeLayer(tooltipRef.current);
        tooltipRef.current = null;
      }
    };
  }, [from, to, map]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (polylineRef.current) {
        map.removeLayer(polylineRef.current);
        polylineRef.current = null;
      }
      if (tooltipRef.current) {
        map.removeLayer(tooltipRef.current);
        tooltipRef.current = null;
      }
    };
  }, [map]);

  return null;
}

export default ManualRoute;
