// src/components/LocationSelectionModal.jsx
import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, useMapEvents, useMap } from 'react-leaflet';
import L from 'leaflet';
import { searchAddress, reverseGeocode } from '../services/geocodingService';

// Fix for default markers in Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

// Custom icon for selected location
const selectedIcon = new L.DivIcon({
  className: 'selected-location-pin',
  html: '<div class="selected-pin"></div>',
  iconSize: [26, 42],
  iconAnchor: [13, 42],
  popupAnchor: [0, -42],
});

// Component to handle map clicks
function MapClickHandler({ onLocationSelect }) {
  useMapEvents({
    click: (e) => {
      const { lat, lng } = e.latlng;
      onLocationSelect({ lat, lng });
    },
  });
  return null;
}

// Component to recenter map
function RecenterMap({ center }) {
  const map = useMap();

  useEffect(() => {
    if (center) {
      map.setView(center, map.getZoom());
    }
  }, [center, map]);

  return null;
}

function LocationSelectionModal({ isOpen, onClose, onConfirm, currentCoords, isMobile }) {
  const [selectedLocation, setSelectedLocation] = useState(currentCoords);
  const [useLiveLocation, setUseLiveLocation] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);
  const [mapCenter, setMapCenter] = useState(currentCoords || [0, 0]);

  useEffect(() => {
    if (isOpen && currentCoords) {
      setSelectedLocation(currentCoords);
      setMapCenter(currentCoords);
      setUseLiveLocation(true);
    }
  }, [isOpen, currentCoords]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    try {
      const results = await searchAddress(searchQuery);
      setSearchResults(results);
    } catch (error) {
      console.error('Search failed:', error);
    } finally {
      setIsSearching(false);
    }
  };

  const handleResultSelect = (result) => {
    setSelectedLocation({ lat: result.lat, lng: result.lng });
    setMapCenter([result.lat, result.lng]);
    setUseLiveLocation(false);
    setSearchResults([]);
    setSearchQuery(result.displayName);
  };

  const handleMapClick = (coords) => {
    setSelectedLocation(coords);
    setUseLiveLocation(false);

    reverseGeocode(coords.lat, coords.lng).then((address) => {
      if (address) setSearchQuery(address);
    });
  };

  const handleConfirm = () => {
    if (!selectedLocation) {
      alert('Please select a location.');
      return;
    }

    onConfirm(selectedLocation);
    onClose();
  };

  const handleUseLive = () => {
    setSelectedLocation(currentCoords);
    setUseLiveLocation(true);
    setMapCenter(currentCoords);
  };

  if (!isOpen) return null;

  const styles = {
    modal: {
      position: 'fixed',
      inset: 0,
      background: 'rgba(2, 6, 23, 0.55)',
      backdropFilter: 'blur(6px)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: isMobile ? '12px' : '24px',
      zIndex: 10000,
    },
    content: {
      background: '#ffffff',
      width: '100%',
      maxWidth: '640px',
      height: isMobile ? '92vh' : 'min(88vh, 760px)',
      borderRadius: '22px',
      boxShadow: '0 24px 80px rgba(15, 23, 42, 0.22)',
      border: '1px solid rgba(148, 163, 184, 0.16)',
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
    },
    header: {
      padding: isMobile ? '18px 18px 12px' : '22px 22px 14px',
      borderBottom: '1px solid #eef2f7',
      background: '#ffffff',
    },
    body: {
      flex: 1,
      overflowY: 'auto',
      padding: isMobile ? '14px 18px' : '18px 22px',
      background: '#fcfcfd',
    },
    footer: {
      position: 'sticky',
      bottom: 0,
      padding: isMobile ? '14px 18px 18px' : '16px 22px 22px',
      borderTop: '1px solid #eef2f7',
      background: 'rgba(255, 255, 255, 0.96)',
      backdropFilter: 'blur(8px)',
      display: 'flex',
      gap: '10px',
    },
    title: {
      margin: 0,
      fontSize: '1.2rem',
      fontWeight: 700,
      letterSpacing: '-0.03em',
      color: '#0f172a',
    },
    subtitle: {
      margin: '6px 0 0',
      color: '#64748b',
      fontSize: '0.92rem',
      lineHeight: 1.45,
    },
    sectionLabel: {
      margin: '0 0 10px',
      color: '#334155',
      fontSize: '0.94rem',
      fontWeight: 600,
    },
    liveButton: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '12px',
      border: useLiveLocation ? '1px solid transparent' : '1px solid #dbe3ee',
      background: useLiveLocation ? '#0f172a' : '#f8fafc',
      color: useLiveLocation ? '#ffffff' : '#0f172a',
      fontWeight: 600,
      fontSize: '0.92rem',
      cursor: 'pointer',
      transition: 'all 0.2s ease',
    },
    searchRow: {
      display: 'flex',
      gap: '8px',
      marginBottom: '12px',
      alignItems: 'stretch',
    },
    input: {
      flex: 1,
      minWidth: 0,
      padding: '11px 14px',
      borderRadius: '12px',
      border: '1px solid #dbe3ee',
      background: '#ffffff',
      color: '#0f172a',
      fontSize: '0.94rem',
      outline: 'none',
    },
    searchButton: {
      padding: '0 14px',
      minWidth: '90px',
      borderRadius: '12px',
      border: '1px solid transparent',
      background: '#2563eb',
      color: '#ffffff',
      fontWeight: 600,
      fontSize: '0.9rem',
      cursor: 'pointer',
      whiteSpace: 'nowrap',
    },
    resultsList: {
      listStyle: 'none',
      padding: 0,
      margin: '0 0 12px',
      border: '1px solid #e2e8f0',
      borderRadius: '14px',
      overflow: 'hidden',
      background: '#ffffff',
      boxShadow: '0 8px 24px rgba(15, 23, 42, 0.05)',
    },
    resultItem: {
      cursor: 'pointer',
      padding: '11px 13px',
      color: '#0f172a',
      fontSize: '0.92rem',
      lineHeight: 1.4,
      background: '#ffffff',
    },
    mapWrap: {
      height: isMobile ? '260px' : '320px',
      borderRadius: '18px',
      overflow: 'hidden',
      border: '1px solid #e2e8f0',
      boxShadow: '0 10px 30px rgba(15, 23, 42, 0.06)',
      background: '#e2e8f0',
    },
    secondaryButton: {
      flex: 1,
      padding: '11px 14px',
      background: '#f8fafc',
      color: '#0f172a',
      border: '1px solid #dbe3ee',
      borderRadius: '12px',
      fontWeight: 600,
      fontSize: '0.92rem',
      cursor: 'pointer',
    },
    primaryButton: {
      flex: 1,
      padding: '11px 14px',
      background: '#2563eb',
      color: '#ffffff',
      border: '1px solid transparent',
      borderRadius: '12px',
      fontWeight: 600,
      fontSize: '0.92rem',
      cursor: 'pointer',
      boxShadow: '0 10px 24px rgba(37, 99, 235, 0.22)',
    },
  };

  return (
    <div style={styles.modal}>
      <div style={styles.content}>
        <div style={styles.header}>
          <h3 style={styles.title}>Pickup Location</h3>
          <p style={styles.subtitle}>Search for an address or tap on the map to choose a custom pickup point.</p>
        </div>

        <div style={styles.body}>
          <div style={{ marginBottom: '16px' }}>
            <button
              onClick={handleUseLive}
              style={styles.liveButton}
              onMouseEnter={(e) => {
                if (!useLiveLocation) {
                  e.currentTarget.style.backgroundColor = '#f1f5f9';
                }
              }}
              onMouseLeave={(e) => {
                if (!useLiveLocation) {
                  e.currentTarget.style.backgroundColor = '#f8fafc';
                }
              }}
            >
              Use Live Location
            </button>
          </div>

          <div>
            <h4 style={styles.sectionLabel}>Custom pickup</h4>

            <div style={styles.searchRow}>
              <input
                type="text"
                placeholder="Search for an address..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                style={styles.input}
              />
              <button
                onClick={handleSearch}
                disabled={isSearching}
                style={{
                  ...styles.searchButton,
                  opacity: isSearching ? 0.8 : 1,
                  cursor: isSearching ? 'default' : 'pointer',
                }}
              >
                {isSearching ? 'Searching...' : 'Search'}
              </button>
            </div>

            {searchResults.length > 0 && (
              <ul style={styles.resultsList}>
                {searchResults.map((result, index) => (
                  <li
                    key={index}
                    onClick={() => handleResultSelect(result)}
                    style={{
                      ...styles.resultItem,
                      borderBottom:
                        index < searchResults.length - 1 ? '1px solid #eef2f7' : 'none',
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.backgroundColor = '#f8fafc';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.backgroundColor = '#ffffff';
                    }}
                  >
                    {result.displayName}
                  </li>
                ))}
              </ul>
            )}

            <div style={styles.mapWrap}>
              <MapContainer
                center={mapCenter}
                zoom={13}
                style={{ height: '100%', width: '100%' }}
              >
                <TileLayer
                  url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                  attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                />
                <MapClickHandler onLocationSelect={handleMapClick} />
                <RecenterMap center={mapCenter} />
                {selectedLocation && (
                  <Marker
                    position={[selectedLocation.lat, selectedLocation.lng]}
                    icon={selectedIcon}
                  />
                )}
              </MapContainer>
            </div>
          </div>
        </div>

        <div style={styles.footer}>
          <button
            onClick={onClose}
            style={styles.secondaryButton}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = '#f1f5f9';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = '#f8fafc';
            }}
          >
            Cancel
          </button>

          <button
            onClick={handleConfirm}
            style={styles.primaryButton}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-1px)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
            }}
          >
            Confirm Location
          </button>
        </div>
      </div>
    </div>
  );
}

export default LocationSelectionModal;